WITH with_gaps AS (SELECT *, CASE WHEN reading_ts - LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) > INTERVAL '30' MINUTE THEN 1 ELSE 0 END AS new_group_flag FROM device_readings), sessionized AS (SELECT id, device_code, reading_ts, pressure, status_bits, SUM(new_group_flag) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps) SELECT CASE WHEN session_no >= 6 THEN 'LARGE' ELSE 'SMALL' END AS session_no_tier, CASE WHEN pressure >= 1018 THEN 'HIGH' ELSE 'LOW' END AS pressure_tier, ROUND(AVG(status_bits), 2) AS avg_status_bits, ROUND(AVG(pressure), 2) AS avg_pressure, COUNT(DISTINCT id) AS distinct_ids, RANK() OVER (PARTITION BY CASE WHEN session_no >= 6 THEN 'LARGE' ELSE 'SMALL' END ORDER BY ROUND(AVG(pressure), 2) DESC) AS avg_pressure_rank FROM sessionized GROUP BY CASE WHEN session_no >= 6 THEN 'LARGE' ELSE 'SMALL' END, CASE WHEN pressure >= 1018 THEN 'HIGH' ELSE 'LOW' END ORDER BY pressure_tier DESC;
